            if (pattern.length() > 0) {
                pattern.append("|").append(entry.getKey()).append("=").append(entry.getValue());
            } else {
                pattern.append(entry.getKey()).append("=").append(entry.getValue());
            }
        }
        return pattern.toString();
    }

